  "inlineSchema": "// FILE: prisma/schema.prisma\n// Master Enterprise Schema v6.1: The 6-Pillar Empire & Moneyball Upgrade\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ngenerator frontendClient {\n  provider = \"prisma-client-js\"\n  output   = \"../frontend/node_modules/.prisma/client\"\n}\n\ndatasource db {\n  provider  = \"postgresql\"\n  url       = env(\"DATABASE_URL\")\n  directUrl = env(\"DIRECT_URL\")\n}\n\n// ----------------------------------------------------\n// 1. SQUAD & PLAYERS\n// ----------------------------------------------------\nmodel Player {\n  id          Int       @id @default(autoincrement())\n  espnId      String    @unique\n  name        String\n  firstname   String?\n  lastname    String?\n  age         Int?\n  birthDate   DateTime?\n  nationality String?\n  height      String?\n  weight      String?\n  number      Int?\n  position    String?\n  photo       String?\n\n  squadRole String @default(\"SENIOR\")\n  metadata  Json   @default(\"{}\")\n\n  preferredFoot String?\n  contractEnd   DateTime?\n  agent         String?\n  bootSponsor   String?\n\n  isActiveSquad Boolean @default(true)\n  isOnLoan      Boolean @default(false)\n  loanClub      String?\n  injured       Boolean @default(false)\n  injuryDetail  String?\n  injuryReturn  String?\n\n  mediaSentiment Float?\n  aiSummary      String?\n\n  matchStats    MatchStat[]\n  transfers     Transfer[]\n  attributes    PlayerAttribute?\n  marketValues  MarketValue[]\n  careerHistory CareerHistory[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// ----------------------------------------------------\n// 2. MATCHES & REALTIME EVENTS\n// ----------------------------------------------------\nmodel Match {\n  id           Int      @id @default(autoincrement())\n  apiFixtureId Int      @unique\n  date         DateTime\n  status       String\n  statusLong   String?\n  elapsed      Int?\n  venue        String?\n  referee      String?\n  competition  String\n  round        String?\n  season       Int\n\n  homeTeamId   Int\n  homeTeamName String\n  homeTeamLogo String\n  homeScore    Int?\n\n  awayTeamId   Int\n  awayTeamName String\n  awayTeamLogo String\n  awayScore    Int?\n\n  halftimeScore String?\n  fulltimeScore String?\n\n  homeGoalscorers Json?\n  awayGoalscorers Json?\n  cards           Json?\n  substitutions   Json?\n  shotData        Json?\n\n  teamStats     Json?\n  intervalStats Json?\n\n  stats MatchStat[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// ----------------------------------------------------\n// 3. MATCH STATS & OPTA ANALYTICS\n// ----------------------------------------------------\nmodel MatchStat {\n  id       Int     @id @default(autoincrement())\n  matchId  Int\n  match    Match   @relation(fields: [matchId], references: [id], onDelete: Cascade)\n  playerId Int?\n  player   Player? @relation(fields: [playerId], references: [id], onDelete: SetNull)\n\n  minutes       Int     @default(0)\n  rating        Float?\n  goals         Int     @default(0)\n  assists       Int     @default(0)\n  shotsTotal    Int     @default(0)\n  shotsOnTarget Int     @default(0)\n  passesTotal   Int     @default(0)\n  passesKey     Int     @default(0)\n  passAccuracy  Float?\n  tackles       Int     @default(0)\n  blocks        Int     @default(0)\n  interceptions Int     @default(0)\n  duelsTotal    Int     @default(0)\n  duelsWon      Int     @default(0)\n  yellowCards   Int     @default(0)\n  redCards      Int     @default(0)\n  saves         Int     @default(0)\n  goalsConceded Int     @default(0)\n  cleanSheet    Boolean @default(false)\n\n  xG                  Float?\n  xA                  Float?\n  npXG                Float?\n  xGBuildup           Float?\n  progressivePasses   Int?\n  progressiveCarries  Int?\n  shotCreatingActions Int?\n\n  rawStatsJson Json?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// ----------------------------------------------------\n// 4. FINANCIAL VAULT & TRANSFERS\n// ----------------------------------------------------\nmodel Transfer {\n  id            Int       @id @default(autoincrement())\n  playerId      Int?\n  player        Player?   @relation(fields: [playerId], references: [id], onDelete: SetNull)\n  playerName    String\n  season        String\n  window        String\n  date          DateTime?\n  isIncoming    Boolean\n  otherClub     String\n  otherClubLogo String?\n  fee           String\n  transferType  String\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// ----------------------------------------------------\n// 5. PLAYER ATTRIBUTES (FBref Radar Charts)\n// ----------------------------------------------------\nmodel PlayerAttribute {\n  id       Int    @id @default(autoincrement())\n  playerId Int    @unique\n  player   Player @relation(fields: [playerId], references: [id], onDelete: Cascade)\n\n  pace      Float @default(50.0)\n  shooting  Float @default(50.0)\n  passing   Float @default(50.0)\n  dribbling Float @default(50.0)\n  defending Float @default(50.0)\n  physical  Float @default(50.0)\n\n  updatedAt DateTime @updatedAt\n}\n\n// ----------------------------------------------------\n// 6. MARKET VALUE EVOLUTION\n// ----------------------------------------------------\nmodel MarketValue {\n  id            Int      @id @default(autoincrement())\n  playerId      Int\n  player        Player   @relation(fields: [playerId], references: [id], onDelete: Cascade)\n  date          DateTime\n  year          Int\n  valueMillions Float\n  clubName      String?\n\n  createdAt DateTime @default(now())\n}\n\n// ----------------------------------------------------\n// 7. CAREER HISTORY\n// ----------------------------------------------------\nmodel CareerHistory {\n  id          Int     @id @default(autoincrement())\n  playerId    Int\n  player      Player  @relation(fields: [playerId], references: [id], onDelete: Cascade)\n  clubName    String\n  clubLogo    String?\n  season      String\n  appearances Int     @default(0)\n  goals       Int     @default(0)\n  assists     Int     @default(0)\n\n  createdAt DateTime @default(now())\n}\n\n// ----------------------------------------------------\n// 8. 3D TROPHY CABINET\n// ----------------------------------------------------\nmodel Trophy {\n  id              Int      @id @default(autoincrement())\n  competitionName String   @unique\n  totalCount      Int      @default(0)\n  winningSeasons  String[]\n  trophyImage     String?\n\n  updatedAt DateTime @updatedAt\n}\n\n// ----------------------------------------------------\n// 9. HISTORICAL TOURNAMENT LEDGER\n// ----------------------------------------------------\nmodel HistoricalCampaign {\n  id          Int     @id @default(autoincrement())\n  season      String\n  competition String\n  milestone   String\n  isChampion  Boolean @default(false)\n\n  createdAt DateTime @default(now())\n}\n\n// ----------------------------------------------------\n// 10. MANAGER DOSSIER\n// ----------------------------------------------------\nmodel Manager {\n  id            Int       @id @default(autoincrement())\n  name          String\n  photo         String?\n  appointedDate DateTime\n  leftDate      DateTime?\n  isCurrent     Boolean   @default(true)\n\n  totalMatches   Int     @default(0)\n  wins           Int     @default(0)\n  draws          Int     @default(0)\n  losses         Int     @default(0)\n  winPercentage  Float?\n  preferredShape String?\n  transferSpend  Float?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n",
